class Solution {
public:
    int minOperations(string initial, string target) {
        int n = initial.size(), m = target.size(), best = 0;
        vector<int> prev(m + 1, 0), cur(m + 1, 0);
        for (int i = 1; i <= n; i++) {
            fill(cur.begin(), cur.end(), 0);
            for (int j = 1; j <= m; j++)
                if (initial[i - 1] == target[j - 1]) {
                    cur[j] = prev[j - 1] + 1;
                    best = max(best, cur[j]);
                }
            swap(prev, cur);
        }
        return n + m - 2 * best;
    }
};

