class Solution {
    public int minOperations(String initial, String target) {
        int n = initial.length(), m = target.length(), best = 0;
        int[] prev = new int[m + 1], cur = new int[m + 1];
        for (int i = 1; i <= n; i++) {
            java.util.Arrays.fill(cur, 0);
            char ci = initial.charAt(i - 1);
            for (int j = 1; j <= m; j++)
                if (ci == target.charAt(j - 1)) {
                    cur[j] = prev[j - 1] + 1;
                    best = Math.max(best, cur[j]);
                }
            int[] tmp = prev; prev = cur; cur = tmp;
        }
        return n + m - 2 * best;
    }
}

