var minOperations = function(initial, target) {
    const n = initial.length, m = target.length;
    let prev = new Array(m + 1).fill(0), best = 0;
    for (let i = 1; i <= n; i++) {
        const cur = new Array(m + 1).fill(0);
        for (let j = 1; j <= m; j++)
            if (initial[i - 1] === target[j - 1]) {
                cur[j] = prev[j - 1] + 1;
                best = Math.max(best, cur[j]);
            }
        prev = cur;
    }
    return n + m - 2 * best;
};
